const items = $input.all();
const cleanItems = [];

for (const item of items) {
    const data = item.json;
    if (!data.url) continue;

    // Clean URL
    const cleanUrl = data.url.trim();
    const url = cleanUrl.toLowerCase();

    const isSwiggy = url.includes('swiggy.com');
    const isBSE = url.includes('bseindia.com');

    cleanItems.push({
        json: {
            ...data,
            url: cleanUrl,
            source: isSwiggy ? 'swiggy' : (isBSE ? 'bse' : 'other')
        }
    });
}

return cleanItems;

const items = $input.all();
const successful = [];

for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item.error) continue;
    if (!item.binary || !item.binary.data) continue;
    successful.push(item);
}

return successful;

const root = "https://www.screener.in";
const results = [];

const item = $input.first().json;

// Get NSE Symbol
let nseSymbol = "UNKNOWN";
try {
    nseSymbol = $('Webhook3').first().json.body.nse_symbol;
} catch (e) {
    if (item.body && item.body.nse_symbol) nseSymbol = item.body.nse_symbol;
}

// --- 1. ANNUAL REPORT ---
if (item.annual_report) {
    let url = item.annual_report;
    if (url.startsWith('/')) url = root + url;

    let today = new Date();
    let calYear = today.getFullYear();
    let arFYNum = today.getMonth() >= 6 ? (calYear % 100) : ((calYear - 1) % 100);
    let arFYString = `FY${arFYNum}`;

    results.push({
        url: url,
        filename: `${nseSymbol} - ${arFYString} - Annual Report.pdf`,
        type: "Annual Report",
        quarter: arFYString
    });
}

// --- 2. CONCALL LINKS & PPTS ---
if (item.concall_links && Array.isArray(item.concall_links)) {
    let transcriptCount = 0;
    let pptCount = 0;

    for (let i = 0; i < item.concall_links.length; i++) {
        const htmlChunk = item.concall_links[i];

        // Extract all <a> tags inside the block
        const linkMatches = htmlChunk.match(/<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi) || [];

        for (const linkHtml of linkMatches) {
            const hrefMatch = linkHtml.match(/href=["']([^"']+)["']/i);
            if (!hrefMatch) continue;

            let url = hrefMatch[1];
            if (url.startsWith('/')) url = root + url;

            const lowerUrl = url.toLowerCase();
            const lowerText = linkHtml.replace(/<[^>]+>/g, '').toLowerCase().trim();

            // Derive a quarter label or fallback to sequence number
            const qMatch = htmlChunk.match(/Q[1-4]\s*FY\d{2,4}/i);
            const quarterLabel = qMatch ? qMatch[0].toUpperCase() : `Recent ${transcriptCount + 1}`;

            // Check for Concall Transcript
            if ((lowerUrl.includes('transcript') || lowerText.includes('transcript')) && !lowerUrl.includes('youtube') && transcriptCount < 4) {
                transcriptCount++;
                results.push({
                    url: url,
                    filename: `${nseSymbol} - ${quarterLabel} - Concall Transcript.pdf`,
                    type: "Concall Transcript",
                    quarter: quarterLabel
                });
            }

            // Check for Investor PPT
            if ((lowerUrl.includes('presentation') || lowerUrl.includes('ppt') || lowerText.includes('ppt') || lowerText.includes('presentation')) && pptCount < 1) {
                pptCount++;
                results.push({
                    url: url,
                    filename: `${nseSymbol} - ${quarterLabel} - Investor PPT.pdf`,
                    type: "Investor PPT",
                    quarter: quarterLabel
                });
            }
        }

        if (transcriptCount >= 4 && pptCount >= 1) break;
    }
}

return results.map(res => ({ json: res }));

const allFiles = $input.all();
const folderInfo = $('Final Folder ID1').first().json;
const nseSymbol = $('Webhook3').first().json.body.nse_symbol;

// Sort files by createdTime descending (newest first)
const sortedFiles = allFiles.map(item => item.json).sort((a, b) => {
    return new Date(b.createdTime || 0) - new Date(a.createdTime || 0);
});

const cleanFiles = [];
const seenNames = new Set();

for (const f of sortedFiles) {
    if (!f.name) continue;

    // Clean name and check for duplicates
    const cleanName = f.name.trim();
    if (seenNames.has(cleanName)) continue;
    seenNames.add(cleanName);

    // Explicitly check the file name to assign the perfect category
    let docType = "Document";
    if (cleanName.includes("Concall Transcript")) {
        docType = "Concall Transcript";
    } else if (cleanName.includes("Annual Report")) {
        docType = "Annual Report";
    } else if (cleanName.includes("Investor PPT")) {
        docType = "Investor PPT";
    } else if (cleanName.includes("Financial Model") || cleanName.includes("Excel")) {
        docType = "Financial Model";
    } else if (cleanName.includes("Podcast") || cleanName.includes("Audio")) {
        docType = "Podcast";
    } else if (cleanName.includes("Video")) {
        docType = "Video";
    }

    cleanFiles.push({
        id: f.id,
        name: cleanName,
        type: docType, 
        webViewLink: f.webViewLink || "Link not fetched",
        webContentLink: f.webContentLink || "Download not fetched",
        createdTime: f.createdTime
    });
}

// Optional: Sort cleanFiles alphabetically by name for a cleaner UI list
cleanFiles.sort((a, b) => a.name.localeCompare(b.name));

return [{
    json: {
        status: "success",
        company: nseSymbol,
        main_folder_id: folderInfo.id,
        total_files: cleanFiles.length,
        files: cleanFiles
    }
}];

const staticData = $getWorkflowStaticData('global');
return [{
  json: {
    url: staticData.__currentUrl || '',
    filename: staticData.__currentFilename || ''
  },
  pairedItem: { item: 0 }
}];

const items = $input.all();

// Seed folders to ensure they are created
const seedFolders = [
  { type: "Annual Report", filename: "" },
  { type: "Concall Transcript", filename: "" },
  { type: "Investor PPT", filename: "" },
  { type: "Financial Model", filename: "" },
  { type: "Research Report", filename: "" },
  { type: "Broker Report", filename: "" }, // <-- ADDED BROKER REPORT
  { type: "Podcast", filename: "" },
  { type: "Video", filename: "" },
  { type: "Other Documents", filename: "" } 
];

const result = [];

// 1. Keep original items and preserve their pairing
for (let i = 0; i < items.length; i++) {
  result.push({
    json: items[i].json,
    binary: items[i].binary,
    pairedItem: {
      item: i
    }
  });
}

// 2. Append seed folders and pair them with the first input item (index 0)
for (const folder of seedFolders) {
  result.push({
    json: folder,
    pairedItem: {
      item: 0
    }
  });
}

return result;

const staticData = $getWorkflowStaticData('global');
const item = $input.first();
staticData.__currentUrl = item.json.url || '';
staticData.__currentFilename = item.json.filename || '';
return [item];

const item = $input.first().json.body;

let mimeType = 'application/pdf';
const filename = item.file_name ? item.file_name.toLowerCase() : '';
if (filename.endsWith('.pptx')) {
    mimeType = 'application/vnd.openxmlformats-officedocument.presentationml.presentation';
} else if (filename.endsWith('.xlsx')) {
    mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
} else if (filename.endsWith('.docx')) {
    mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
}

// Default to 'Other Documents' if no subfolder_name is explicitly provided
const subfolderName = item.subfolder_name || 'Other Documents';

const staticData = $getWorkflowStaticData('global');
staticData.__fileName = item.file_name || '';
staticData.__folderId = item.folder_id || '';
staticData.__subfolderName = subfolderName;
staticData.__fileBase64 = item.file_base64 || '';
staticData.__mimeType = mimeType;

return {
    json: {
        fileName: item.file_name,
        folderId: item.folder_id,
        subfolderName: subfolderName
    }
};

const targetFolderId = $input.first().json.targetFolderId;
const staticData = $getWorkflowStaticData('global');

return {
    json: {
        fileName: staticData.__fileName,
        folderId: targetFolderId
    },
    binary: {
        data: {
            data: staticData.__fileBase64,
            mimeType: staticData.__mimeType,
            fileName: staticData.__fileName
        }
    },
    pairedItem: { item: 0 }
};

// Get Company Folder ID from previous step (either existing or newly created)
const companyFolderId = $json.id;

// Format current date as YYYYMMDD
const today = new Date();
const year = today.getFullYear();
const month = String(today.getMonth() + 1).padStart(2, '0');
const day = String(today.getDate()).padStart(2, '0');
const dateStr = `${year}${month}${day}`;

return [{
  json: {
    company_folder_id: companyFolderId,
    date_str: dateStr
  }
}];
